INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('vallum', 'Vallum', '["Erdwall","Befestigung"]', 'Das Vallum war der Erdwall mit aufgesetzter Holzpalisade, der römische Militärlager (castra) und Grenzbefestigungen umgab und die erste Verteidigungslinie bildete. Der Begriff bezeichnete sowohl den Wall selbst als auch die gesamte Befestigungsanlage. Das typische Vallum bestand aus einem aufgeschütteten Erdwall, der aus dem Aushub des davor liegenden Grabens (fossa) gewonnen wurde. Auf der Wallkrone wurden angespitzte Holzpfähle (valli) dicht aneinander gesetzt, die dem Wall seinen Namen gaben. Die Legionäre trugen auf Märschen ihre eigenen Palisadenpfähle mit sich. Bei dauerhaften Befestigungen wie dem Hadrianswall oder dem Limes wurde das Vallum durch Steinmauern ersetzt. Der Bau eines Vallum war tägliche Routine und gehörte zur Grundausbildung jedes Legionärs. Diese Praxis gab Rom einen entscheidenden taktischen Vorteil.', 'Militär & Kriegsführung', 'Von lateinisch ''vallum'' (Palisade, Wall), von ''vallus'' (Pfahl). Die Wurzel bezeichnet die Pfähle, die auf dem Wall aufgestellt wurden.', '["Castra","Fossatum","Limes","Legion"]', '{"en":{"term":"Vallum","definition":"The vallum was the earthen rampart with wooden palisade that surrounded Roman military camps (castra) and frontier fortifications, forming the first line of defense. The term denoted both the wall itself and the entire fortification system. The typical vallum consisted of a raised earthen rampart created from the excavation of the ditch (fossa) in front of it. On the wall crest, sharpened wooden stakes (valli) were set closely together, which gave the wall its name. Legionaries carried their own palisade stakes on marches. In permanent fortifications such as Hadrian''s Wall or the Limes, the vallum was replaced by stone walls. Building a vallum was daily routine and part of the basic training of every legionary. This practice gave Rome a decisive tactical advantage.","etymology":"From Latin ''vallum'' (palisade, rampart), from ''vallus'' (stake). The root refers to the stakes erected on the wall.","category":"Military & Warfare","variants":["Rampart","Palisade Wall"]},"la":{"term":"Vallum","definition":"Vallum fuit agger terrenus cum vallo ligneo qui castra militaria Romana (castra) et munitiones limitaneas circumdabat et primam lineam defensionis formabat. Vocabulum et ipsum murum et totum systema munitionis designabat. Vallum typicum ex aggere terreo erecto constabat qui ex fossione fossae ante eum positus creabatur. In crista aggeris, valli lignei acuti dense collocabantur, qui aggeri nomen dederunt. Legionarii in itineribus proprios vallos portabant. In munitionibus permanentibus ut Vallo Hadriani vel Limite, vallum a muris lapideis substitutum est. Constructio valli munus cotidianum erat et pars disciplinae fundamentalis cuiusque legionarii. Haec usus Romae advantagium tacticum decisivum dedit.","etymology":"A vocabulo Latino ''vallum'' (vallum, agger), a ''vallus'' (vallus). Radix ad vallos in aggere erectos refertur.","category":"Militia et Bellum","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('fossatum', 'Fossatum', '["Graben","Befestigungsgraben"]', 'Das Fossatum (von ''fossa'' - Graben) war der Verteidigungsgraben, der vor dem Wall (vallum) römischer Militärlager und Befestigungsanlagen ausgehoben wurde. Das Ausheben des Fossatum gehörte zu den ersten Aufgaben beim Lagerbau und war Teil der täglichen Routine marschierender Legionen. Der Graben war typischerweise 2-3 Meter tief und 3-4 Meter breit, mit V-förmigem oder steilwandigem Profil. Die ausgehobene Erde wurde zur Aufschüttung des Vallum verwendet. Bei permanenten Befestigungen wie dem Limes waren die Gräben noch tiefer und breiter, manchmal mehrfach angelegt. Das Fossatum diente mehreren Zwecken: Es verlangsamte feindliche Angriffe, erschwerte den Einsatz von Belagerungsmaschinen und bot den Verteidigern Zeit zur Vorbereitung. Entlang der Grenzen entstanden fossata als Teil größerer Verteidigungssysteme. Das Wort lebt in modernen Begriffen wie "Fossat" fort.', 'Militär & Kriegsführung', 'Von lateinisch ''fossa'' (Graben) → ''fossatum'' (gegrabenes Werk). Von ''fodere'' (graben), verwandt mit deutsch "Grube".', '["Vallum","Castra","Limes","Legion"]', '{"en":{"term":"Fossatum","definition":"The fossatum (from ''fossa'' - ditch) was the defensive ditch excavated in front of the rampart (vallum) of Roman military camps and fortifications. Digging the fossatum was one of the first tasks in camp construction and part of the daily routine of marching legions. The ditch was typically 2-3 meters deep and 3-4 meters wide, with a V-shaped or steep-walled profile. The excavated earth was used to build up the vallum. In permanent fortifications such as the Limes, the ditches were even deeper and wider, sometimes multiple. The fossatum served several purposes: it slowed enemy attacks, hindered the deployment of siege engines, and gave defenders time to prepare. Along the frontiers, fossata emerged as part of larger defensive systems. The word survives in modern terms such as ''fossat''.","etymology":"From Latin ''fossa'' (ditch) → ''fossatum'' (dug work). From ''fodere'' (to dig), related to German ''Grube''.","category":"Military & Warfare","variants":["Defensive Ditch"]},"la":{"term":"Fossatum","definition":"Fossatum (a ''fossa'' - fossa) fuit fossa defensiva ante aggerem (vallum) castrorum militarium Romanorum et munitionum efossa. Effodiendi fossatum unum ex primis muneribus in constructione castrorum erat et pars muneris cotidiani legionum iter facientium. Fossa typice duos ad tres passus alta et tres ad quattuor passus lata erat, cum profilo V-formi vel parietibus abrupts. Terra effossa ad extructionem valli adhibebatur. In munitionibus permanentibus ut Limite, fossae etiam altiores et latiores erant, interdum multiplices. Fossatum pluribus propositis serviebat: impetus hostiles retardabat, adhibitionem tormentorum obsidionalium impediebat et defensoribus tempus ad praeparationem dabat. Secundum fines, fossata ut pars systematum defensivorum maiorum emergebant. Vocabulum in vocabulis modernis ut ''fossat'' supervivit.","etymology":"A vocabulo Latino ''fossa'' (fossa) → ''fossatum'' (opus fossum). A ''fodere'' (fodere), cognatum cum Germanico ''Grube''.","category":"Militia et Bellum","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('sica', 'Sica', '["Sichelkrummschwert","Thrakisches Schwert"]', 'Die Sica war ein charakteristisches gebogenes Kurzschwert mit sichelförmiger Klinge, das ursprünglich von den thrakischen Kriegern Südosteuropas verwendet wurde und später zur typischen Waffe des Gladiatorentyps Thraex wurde. Die Klinge war etwa 40-45 cm lang und nach innen gebogen, ähnlich einer Sichel, was ihr den Namen gab (lat. ''sica'' = Dolch, von ''secare'' = schneiden). Diese Form ermöglichte es, um Schilde herum zu schlagen und Gegner durch ungewöhnliche Winkel zu treffen. Die Sica war sowohl Hieb- als auch Stichwaffe. In der römischen Literatur wurde die Sica oft mit Meuchelmord und heimtückischer Gewalt assoziiert – Cicero verwendete den Begriff metaphorisch für politische Attentäter. Die Waffe symbolisierte barbarische Kampfkunst aus römischer Sicht, war aber in der Arena hocheffektiv und beliebt.', 'Militär & Kriegsführung', 'Von lateinisch ''sica'' (Dolch, gebogenes Messer), von ''secare'' (schneiden). Die gebogene Form gab der Waffe ihren Namen.', '["Thraex","Gladius","Gladiator","Pugio"]', '{"en":{"term":"Sica","definition":"The sica was a characteristic curved short sword with a sickle-shaped blade, originally used by the Thracian warriors of southeastern Europe and later becoming the typical weapon of the gladiator type thraex. The blade was about 40-45 cm long and curved inward, similar to a sickle, which gave it its name (Latin ''sica'' = dagger, from ''secare'' = to cut). This shape allowed striking around shields and hitting opponents from unusual angles. The sica was both a cutting and thrusting weapon. In Roman literature, the sica was often associated with assassination and treacherous violence – Cicero used the term metaphorically for political assassins. The weapon symbolized barbaric martial arts from the Roman perspective but was highly effective and popular in the arena.","etymology":"From Latin ''sica'' (dagger, curved knife), from ''secare'' (to cut). The curved shape gave the weapon its name.","category":"Military & Warfare","variants":["Curved Dagger","Thracian Sword"]},"la":{"term":"Sica","definition":"Sica fuit gladius brevis curvus characteristicus cum lamina falciformi, initio a militibus Thracibus Europae sudorientalis adhibitus et postea arma typica generis gladiatoris thraex factus. Lamina circa quadraginta ad quadraginta quinque centimetra longa erat et introrsum curvata, similis falci, quod ei nomen dedit (Latinum ''sica'' = pugio, a ''secare'' = secare). Haec forma circa scuta ferire et adversarios ex angulis insolitis percutere permittebat. Sica et arma caesoria et punctoria erat. In litteratura Romana, sica saepe cum homicidio et violentia perfida associabatur – Cicero vocabulum metaphorice pro sicariis politicis adhibebat. Arma artes martiales barbaricas ex perspectiva Romana symbolizabat sed in arena valde efficax et popularis erat.","etymology":"A vocabulo Latino ''sica'' (pugio, culter curvus), a ''secare'' (secare). Forma curvata arma nomen dedit.","category":"Militia et Bellum","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('pugio', 'Pugio', '["Dolch","Römischer Dolch"]', 'Der Pugio war der standardisierte römische Dolch, der von Legionären als Sekundärwaffe getragen wurde und sowohl militärisch als auch zivil von großer Bedeutung war. Mit einer etwa 20-30 cm langen, breiten, doppelschneidigen Klinge war der Pugio eine effektive Nahkampfwaffe für dichte Formationen. Die Klinge hatte typischerweise eine charakteristische blattförmige Form mit breitester Stelle in der Mitte. Legionäre trugen den Pugio auf der linken Seite am Gürtel (cingulum militare), gegenüber dem Gladius auf der rechten Seite. Der Pugio war nicht nur Waffe, sondern auch Werkzeug und Statussymbol. Die prachtvollsten Exemplare hatten verzierte Scheiden und Griffe mit Einlegearbeiten aus Edelmetall. Julius Caesar wurde bekanntlich mit Pugiones ermordet. In der Spätantike verschwand der Pugio allmählich aus der militärischen Ausrüstung.', 'Militär & Kriegsführung', 'Von lateinisch ''pugio'' (Dolch), möglicherweise verwandt mit ''pugnus'' (Faust) – eine Waffe für den Faustgriff.', '["Gladius","Legion","Centurio","Cingulum"]', '{"en":{"term":"Pugio","definition":"The pugio was the standardized Roman dagger carried by legionaries as a secondary weapon and was of great importance both militarily and civilly. With a blade about 20-30 cm long, wide, and double-edged, the pugio was an effective close combat weapon for dense formations. The blade typically had a characteristic leaf-shaped form with the widest point in the middle. Legionaries wore the pugio on the left side of the belt (cingulum militare), opposite the gladius on the right side. The pugio was not only a weapon but also a tool and status symbol. The most magnificent examples had decorated sheaths and hilts with inlays of precious metal. Julius Caesar was famously murdered with pugiones. In late antiquity, the pugio gradually disappeared from military equipment.","etymology":"From Latin ''pugio'' (dagger), possibly related to ''pugnus'' (fist) – a weapon for fist grip.","category":"Military & Warfare","variants":["Dagger","Roman Dagger"]},"la":{"term":"Pugio","definition":"Pugio fuit pugio Romanus standardizatus a legionariis ut arma secundaria portatus et magni momenti et militariter et civiliter erat. Cum lamina circa viginti ad triginta centimetra longa, lata et duplici acie, pugio arma corporalis efficax pro formationibus densis erat. Lamina typice formam characteristicam foliatam cum puncto latissimo in medio habebat. Legionarii pugionem in latere sinistro cinguli (cingulum militare) portabant, contra gladium in latere dextro. Pugio non tantum arma sed etiam instrumentum et symbolum status erat. Exemplaria magnificentissima vaginas et capulos ornatos cum insertionibus metalli pretiosi habebant. Iulius Caesar celebriter cum pugionibus occisus est. Antiquitate sera, pugio paulatim ex armamento militari evanuit.","etymology":"A vocabulo Latino ''pugio'' (pugio), fortasse cognatum cum ''pugnus'' (pugnus) – arma pro prehensione pugni.","category":"Militia et Bellum","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('via-praetoria', 'Via Praetoria', '["Hauptstraße","Lagerstraße"]', 'Die Via Praetoria war eine der beiden Hauptstraßen im standardisierten Grundriss römischer Militärlager (castra) und verlief vom Haupttor (porta praetoria) durch das Zentrum bis zum hinteren Teil des Lagers. Sie kreuzte die Via Principalis, die zweite Hauptstraße, im Zentrum beim Prätorium (Kommandantenzelt) und den Principia (Stabsgebäude). Dieser kreuzförmige Straßenplan war in jedem römischen Lager identisch und ermöglichte schnelle Orientierung und effiziente Bewegung der Truppen. Die Via Praetoria war breit genug für marschierende Kohorten und führende Offiziere. Bei permanenten Lagern wurden diese Straßen gepflastert und bildeten das Rückgrat der späteren Städte. Viele moderne europäische Städte bewahren noch heute den römischen Straßenplan. Die Via Praetoria symbolisierte römische Ordnung, Disziplin und militärische Effizienz. Der Name leitet sich vom Prätorium ab, auf das die Straße zuführte.', 'Militär & Kriegsführung', 'Von lateinisch ''via'' (Straße, Weg) + ''praetorium'' (Kommandantenzelt), die Straße zum Prätorium führend.', '["Castra","Praetorium","Via Principalis","Porta Praetoria"]', '{"en":{"term":"Via Praetoria","definition":"The Via Praetoria was one of the two main roads in the standardized layout of Roman military camps (castra) and ran from the main gate (porta praetoria) through the center to the rear of the camp. It crossed the Via Principalis, the second main road, at the center by the praetorium (commander''s tent) and the principia (headquarters building). This cruciform street plan was identical in every Roman camp and enabled rapid orientation and efficient troop movement. The Via Praetoria was wide enough for marching cohorts and leading officers. In permanent camps, these roads were paved and formed the backbone of later cities. Many modern European cities still preserve the Roman street plan today. The Via Praetoria symbolized Roman order, discipline, and military efficiency. The name derives from the praetorium to which the road led.","etymology":"From Latin ''via'' (road, way) + ''praetorium'' (commander''s tent), the road leading to the praetorium.","category":"Military & Warfare","variants":["Main Camp Road"]},"la":{"term":"Via Praetoria","definition":"Via Praetoria fuit una ex duabus viis principalibus in plano standardizato castrorum militarium Romanorum (castra) et a porta principali (porta praetoria) per centrum ad partem posteriorem castrorum ducebat. Viam Principalem, secundam viam principalem, in centro apud praetorium (tabernaculum ducis) et principia (aedificium praefecturae) cruciabat. Hic planus viarum cruciformis in omnibus castris Romanis identicus erat et orientationem celerem et motum efficientem copiarum permittebat. Via Praetoria satis lata pro cohortibus iter facientibus et officialibus ducentibus erat. In castris permanentibus, hae viae stratae erant et spinam dorsalem urbium posteriorum formabant. Multae urbes Europaeae modernae planum viarum Romanum adhuc hodie conservant. Via Praetoria ordinem Romanum, disciplinam et efficientiam militarem symbolizabat. Nomen a praetorio derivatur ad quod via ducebat.","etymology":"A vocabulo Latino ''via'' (via, iter) + ''praetorium'' (tabernaculum ducis), via ad praetorium ducens.","category":"Militia et Bellum","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('cingulum-militare', 'Cingulum Militare', '["Militärgürtel","Römischer Militärgurt"]', 'Das Cingulum Militare war der charakteristische römische Militärgürtel, den Legionäre und Offiziere als Teil ihrer Standard-Uniform trugen und der sowohl praktische als auch symbolische Bedeutung hatte. Der breite Ledergürtel war mit Bronze- oder Messingplatten verziert und hatte mehrere Funktionen: Er trug das Gladius (auf der rechten Seite) und den Pugio (auf der linken Seite), stützte den Rücken bei langen Märschen und zeigte den militärischen Status. Vom Gürtel hingen mehrere Lederriemen (pteruges) herab, die die Leistengegend schützten und teilweise mit Metallenden beschwert waren. Das Cingulum war ein Zeichen aktiven Militärdienstes – es anzulegen bedeutete "unter Waffen treten" (cingulum sumere), es abzulegen bedeutete aus dem Dienst auszuscheiden. Prachtvolle Exemplare mit Silber- oder Goldverzierungen zeigten Rang und Verdienste. Das Cingulum symbolisierte römische Disziplin und Militärmacht.', 'Militär & Kriegsführung', 'Von lateinisch ''cingulum'' (Gürtel), von ''cingere'' (umgürten, umschließen) + ''militare'' (militärisch). Wörtlich "Militärgürtel".', '["Gladius","Pugio","Legion","Balteus"]', '{"en":{"term":"Cingulum Militare","definition":"The cingulum militare was the characteristic Roman military belt worn by legionaries and officers as part of their standard uniform and had both practical and symbolic significance. The wide leather belt was decorated with bronze or brass plates and had several functions: it carried the gladius (on the right side) and the pugio (on the left side), supported the back during long marches, and displayed military status. Several leather straps (pteruges) hung from the belt, protecting the groin area and partly weighted with metal ends. The cingulum was a sign of active military service – putting it on meant ''taking up arms'' (cingulum sumere), taking it off meant leaving service. Magnificent examples with silver or gold decorations showed rank and merit. The cingulum symbolized Roman discipline and military power.","etymology":"From Latin ''cingulum'' (belt), from ''cingere'' (to gird, enclose) + ''militare'' (military). Literally ''military belt''.","category":"Military & Warfare","variants":["Military Belt"]},"la":{"term":"Cingulum Militare","definition":"Cingulum militare fuit cingulum militare Romanum characteristicum a legionariis et officialibus ut pars uniformis standardis portatum et significationem et practicam et symbolicam habebat. Cingulum latum coriaceum laminis aeneis vel auricalceis ornatum erat et plures functiones habebat: gladium (in latere dextro) et pugionem (in latere sinistro) portabat, dorsum in itineribus longis sustinebat et statum militarem monstrabat. Plures lora coriacea (pteruges) a cingulo pendebant, regionem inguinalem protegentia et partim finibus metallicis ponderata. Cingulum signum servitii militaris activi erat – eum sumere ''arma sumere'' (cingulum sumere) significabat, eum deponere ex servitio excedere significabat. Exemplaria magnifica cum ornamentis argenteis vel aureis gradum et merita monstrabant. Cingulum disciplinam Romanam et potentiam militarem symbolizabat.","etymology":"A vocabulo Latino ''cingulum'' (cingulum), a ''cingere'' (cingere, circumdare) + ''militare'' (militare). Litteraliter ''cingulum militare''.","category":"Militia et Bellum","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('murmillo', 'Murmillo', '["Mirmillo","Gladiatorentyp"]', 'Der Murmillo (auch Mirmillo) war ein Gladiatorentyp, der nach einem Fisch (griech. ''mormyros'') benannt wurde, dessen stilisierte Form seinen Helm zierte. Er war mit schwerer Rüstung ausgestattet: einem großen rechteckigen Schild (scutum) wie ein Legionär, einem Kurzschwert (gladius), einem Helm mit Kamm und Visier, einem Beinschoner (ocrea) am linken Bein und einem Armschutz (manica) am rechten Arm. Der Murmillo kämpfte typischerweise gegen den netzführenden Retiarius oder den leichter gerüsteten Thraex. Sein Kampfstil war defensiv und ausdauernd, da er sich auf seine schwere Panzerung verließ. Die Duelle zwischen Murmillo und Retiarius waren besonders populär, da sie den Gegensatz zwischen schwer gerüstetem Infanteristen und beweglichem Kämpfer darstellten. Die Ausrüstung des Murmillo war an römische Legionäre angelehnt und symbolisierte römische Militärmacht.', 'Unterhaltung & Sport', 'Von griechisch ''μορμύρος'' (mormyros, eine Fischart) → lateinisch ''murmillo''. Der Helm trug eine Fischdarstellung als Kamm.', '["Gladiator","Retiarius","Thraex","Amphitheater"]', '{"en":{"term":"Murmillo","definition":"The murmillo (also mirmillo) was a type of gladiator named after a fish (Greek ''mormyros'') whose stylized form adorned his helmet. He was equipped with heavy armor: a large rectangular shield (scutum) like a legionary, a short sword (gladius), a helmet with crest and visor, a shin guard (ocrea) on the left leg, and an arm guard (manica) on the right arm. The murmillo typically fought against the net-wielding retiarius or the more lightly armored thraex. His fighting style was defensive and enduring, as he relied on his heavy armor. Duels between murmillo and retiarius were particularly popular, as they represented the contrast between heavily armored infantryman and agile fighter. The murmillo''s equipment was modeled on Roman legionaries and symbolized Roman military might.","etymology":"From Greek ''μορμύρος'' (mormyros, a type of fish) → Latin ''murmillo''. The helmet bore a fish representation as a crest.","category":"Entertainment & Sports","variants":["Mirmillo"]},"la":{"term":"Murmillo","definition":"Murmillo (etiam mirmillo) fuit genus gladiatoris a pisce (Graece ''mormyros'') nominatus cuius forma stilizata galeam eius ornabat. Armatura gravi instructus erat: scuto magno rectangulari (scutum) ut legionarius, gladio brevi (gladius), galea cum crista et visorio, ocrea in crure sinistro et manica in brachio dextro. Murmillo typice contra retiarium rete gerentem vel thracem levius armatum pugnabat. Modus pugnandi eius defensivus et patiens erat quia in armaturam gravem confidebat. Duella inter murmillonem et retiarium praecipue popularia erant quia contrarium inter peditem graviter armatum et pugnatorem agilem repraesentabant. Armatura murmillonis ad legionarios Romanos conformata erat et potentiam militarem Romanam symbolizabat.","etymology":"A vocabulo Graeco ''μορμύρος'' (mormyros, genus piscis) → Latinum ''murmillo''. Galea repraesentationem piscis ut cristam gerebat.","category":"Ludus et Certamen","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('retiarius', 'Retiarius', '["Netzfechter","Netzgladiator"]', 'Der Retiarius (von lat. ''rete'' - Netz) war ein Gladiatorentyp, der mit Netz und Dreizack kämpfte und eine der ungewöhnlichsten und beliebtesten Gladiatorenklassen darstellte. Anders als andere Gladiatoren trug er kaum Rüstung: nur einen Armschutz (manica) am linken Arm und eine Schulterpanzerung (galerus). Seine Hauptwaffen waren ein gewichtetes Netz (rete), ein Dreizack (fuscina oder tridens) und ein Dolch (pugio). Seine Strategie bestand darin, den Gegner mit dem Netz zu fangen und ihn dann mit dem Dreizack niederzustechen. Der Retiarius kämpfte typischerweise gegen den schwer gerüsteten Murmillo oder Secutor. Seine Mobilität und Reichweite waren seine größten Vorteile. Der Kampf zwischen Retiarius und Murmillo symbolisierte den Konflikt zwischen Fischer und Fisch, Agilität und Panzerung. Trotz fehlender Rüstung waren erfolgreiche Retiarii hochgeachtet.', 'Unterhaltung & Sport', 'Von lateinisch ''rete'' (Netz) → ''retiarius'' (Netzmann, Netzfechter). Bezeichnung nach seiner charakteristischen Waffe.', '["Gladiator","Murmillo","Secutor","Amphitheater"]', '{"en":{"term":"Retiarius","definition":"The retiarius (from Latin ''rete'' - net) was a type of gladiator who fought with net and trident and represented one of the most unusual and popular gladiator classes. Unlike other gladiators, he wore almost no armor: only an arm guard (manica) on the left arm and shoulder armor (galerus). His main weapons were a weighted net (rete), a trident (fuscina or tridens), and a dagger (pugio). His strategy was to catch the opponent with the net and then stab him down with the trident. The retiarius typically fought against the heavily armored murmillo or secutor. His mobility and reach were his greatest advantages. The fight between retiarius and murmillo symbolized the conflict between fisherman and fish, agility and armor. Despite lacking armor, successful retiarii were highly respected.","etymology":"From Latin ''rete'' (net) → ''retiarius'' (netman, net-fighter). Named after his characteristic weapon.","category":"Entertainment & Sports","variants":["Net-fighter"]},"la":{"term":"Retiarius","definition":"Retiarius (a Latino ''rete'' - rete) fuit genus gladiatoris qui cum rete et tridente pugnabat et unum ex classibus gladiatorum maxime insolitis et popularibus repraesentabat. Dissimiliter ab aliis gladiatoribus, vix armaturam gerebat: tantum manicam in brachio sinistro et armaturam humeri (galerus). Arma principalia eius erant rete ponderatum (rete), tridens (fuscina vel tridens) et pugio. Strategia eius erat adversarium rete capere et deinde tridente transfigere. Retiarius typice contra murmillonem vel secutorem graviter armatum pugnabat. Mobilitas et amplitudo eius maxima advantagia erant. Pugna inter retiarium et murmillonem conflictum inter piscatorem et piscem, agilitatem et armaturam symbolizabat. Malgre defectu armaturae, retiarii felices magni aestimati erant.","etymology":"A vocabulo Latino ''rete'' (rete) → ''retiarius'' (retiarius, pugnator cum rete). Nominatus ex arma characteristica.","category":"Ludus et Certamen","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('secutor', 'Secutor', '["Verfolger","Gladiatorentyp"]', 'Der Secutor (lat. "Verfolger") war ein spezialisierter Gladiatorentyp, der entwickelt wurde, um gegen den Retiarius (Netzfechter) zu kämpfen. Sein Name bezog sich auf seine Rolle, den beweglichen Retiarius durch die Arena zu verfolgen. Der Secutor war schwer gerüstet mit einem großen ovalen oder rechteckigen Schild (scutum), einem Kurzschwert (gladius), einem geschlossenen, glatten Helm ohne Krempe oder Vorsprünge (damit sich das Netz nicht verfangen konnte), einem Beinschoner (ocrea) am linken Bein und einem Armschutz (manica) am rechten Arm. Sein Helm hatte nur kleine Augenschlitze, was seine Sicht einschränkte, aber Schutz gegen den Dreizack des Retiarius bot. Der Secutor musste schnell sein, da seine schwere Rüstung ihn bei längeren Kämpfen ermüdete. Diese Spezialisierung machte Kämpfe zwischen Secutor und Retiarius zu den populärsten Arenaspektakeln.', 'Unterhaltung & Sport', 'Von lateinisch ''sequi'' (folgen) → ''secutor'' (Verfolger). Benannt nach seiner Taktik, den Retiarius zu verfolgen.', '["Gladiator","Retiarius","Murmillo","Amphitheater"]', '{"en":{"term":"Secutor","definition":"The secutor (Latin ''pursuer'') was a specialized type of gladiator developed to fight against the retiarius (net-fighter). His name referred to his role of pursuing the mobile retiarius through the arena. The secutor was heavily armored with a large oval or rectangular shield (scutum), a short sword (gladius), a closed, smooth helmet without brim or projections (so the net couldn''t catch on it), a shin guard (ocrea) on the left leg, and an arm guard (manica) on the right arm. His helmet had only small eye slits, which limited his vision but offered protection against the retiarius'' trident. The secutor had to be fast, as his heavy armor tired him in longer fights. This specialization made fights between secutor and retiarius the most popular arena spectacles.","etymology":"From Latin ''sequi'' (to follow) → ''secutor'' (pursuer). Named after his tactic of pursuing the retiarius.","category":"Entertainment & Sports","variants":["Pursuer"]},"la":{"term":"Secutor","definition":"Secutor (Latine ''persecutor'') fuit genus gladiatoris specializatum quod contra retiarium (pugnatorem cum rete) pugnare evolutum erat. Nomen eius ad munus retiarium mobilem per arenam persequendi referebat. Secutor graviter armatus erat cum scuto magno ovali vel rectangulari (scutum), gladio brevi (gladius), galea clausa et polita sine limbo vel proiectibus (ne rete comprehendi posset), ocrea in crure sinistro et manica in brachio dextro. Galea eius tantum rimas oculares parvas habebat, quod visum eius limitabat sed protectionem contra tridentem retiarii praebebat. Secutor celer esse debebat quia armatura gravis eum in pugnis longioribus fatigabat. Haec specializatio pugnas inter secutorem et retiarium ad spectacula arenae popularissima faciebat.","etymology":"A vocabulo Latino ''sequi'' (sequi) → ''secutor'' (persecutor). Nominatus ex tactica retiarium persequendi.","category":"Ludus et Certamen","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('thraex', 'Thraex', '["Thraker","Thrakischer Gladiator"]', 'Der Thraex (Plural: Thraces, "Thraker") war ein Gladiatorentyp, dessen Ausrüstung und Kampfstil von den thrakischen Kriegern Südosteuropas inspiriert war. Er war ausgestattet mit einem kleinen rechteckigen oder quadratischen Schild (parmula), einem gebogenen Kurzschwert (sica), einem Helm mit breiter Krempe, hohen Beinschonern (ocreae) an beiden Beinen und Armschützern (manicae). Die charakteristische sica war eine sichelförmige Klinge, die es erlaubte, um das Schild des Gegners herum zu schlagen. Der Thraex war beweglicher als der schwer gerüstete Murmillo und kämpfte häufig gegen diesen oder gegen einen Hoplomachus. Sein aggressiver, offensiver Kampfstil und die ungewöhnliche Waffe machten ihn beim Publikum sehr beliebt. Die hohen Beinschoner waren charakteristisch und boten Schutz gegen niedrige Angriffe. Einige der berühmtesten Gladiatoren, einschließlich Spartacus, waren Thraces.', 'Unterhaltung & Sport', 'Von lateinisch ''Thrax'' (Thraker) → ''thraex''. Benannt nach dem thrakischen Volk und dessen Kampfweise.', '["Gladiator","Murmillo","Sica","Amphitheater"]', '{"en":{"term":"Thraex","definition":"The thraex (plural: thraces, ''Thracian'') was a type of gladiator whose equipment and fighting style was inspired by the Thracian warriors of southeastern Europe. He was equipped with a small rectangular or square shield (parmula), a curved short sword (sica), a helmet with wide brim, high shin guards (ocreae) on both legs, and arm guards (manicae). The characteristic sica was a sickle-shaped blade that allowed striking around the opponent''s shield. The thraex was more mobile than the heavily armored murmillo and frequently fought against him or against a hoplomachus. His aggressive, offensive fighting style and unusual weapon made him very popular with audiences. The high shin guards were characteristic and offered protection against low attacks. Some of the most famous gladiators, including Spartacus, were thraces.","etymology":"From Latin ''Thrax'' (Thracian) → ''thraex''. Named after the Thracian people and their fighting style.","category":"Entertainment & Sports","variants":["Thracian Gladiator"]},"la":{"term":"Thraex","definition":"Thraex (plurale: thraces, ''Thrax'') fuit genus gladiatoris cuius armatura et modus pugnandi a militibus Thracibus Europae sudorientalis inspiratus erat. Instructus erat parmula (scuto parvo rectangulari vel quadrato), sica (gladio brevi curvo), galea cum limbo lato, ocreis altis in utroque crure et manicis. Sica characteristica erat lamina falciformis quae circa scutum adversarii ferire permittebat. Thraex mobilior erat quam murmillo graviter armatus et frequenter contra eum vel contra hoplomachum pugnabat. Modus pugnandi eius aggressivus et offensivus et arma insolita eum apud spectatores valde popularem faciebat. Ocreae altae characteristicae erant et protectionem contra impetus inferiores praebebant. Aliqui gladiatorum celeberrimorum, incluso Spartaco, thraces erant.","etymology":"A vocabulo Latino ''Thrax'' (Thrax) → ''thraex''. Nominatus ex populo Thracio et modo pugnandi eorum.","category":"Ludus et Certamen","variants":[]}}');
